{"content":"import { getDb } from '../db/index.js';
import { FALLBACK_INPUT_PER_M, FALLBACK_OUTPUT_PER_M } from '../db/model-pricing.js';

export interface CostBreakdown {
  model: string;
  platform: string;
  inputTokens: number;
  outputTokens: number;
  cached: boolean;
  inputCostPerM: number;
  outputCostPerM: number;
  inputCost: number;
  outputCost: number;
  cacheDiscount: number;
  cacheSavings: number;
  totalCost: number;
  effectiveCost: number;
}

export interface DailyReport {
  date: string;
  totalRequests: number;
  totalInputTokens: number;
  totalOutputTokens: number;
  totalCost: number;
  totalSavings: number;
  byModel: ModelCostSummary[];
  byProvider: ProviderCostSummary[];
}

export interface MonthlyReport {
  month: string;
  totalRequests: number;
  totalInputTokens: number;
  totalOutputTokens: number;
  totalCost: number;
  totalSavings: number;
  byDay: DailySummary[];
  byModel: ModelCostSummary[];
  byProvider: ProviderCostSummary[];
}

export interface ModelCostSummary {
  model: string;
  platform: string;
  requests: number;
  inputTokens: number;
  outputTokens: number;
  cost: number;
  savings: number;
}

export interface ProviderCostSummary {
  platform: string;
  requests: number;
  inputTokens: number;
  outputTokens: number;
  cost: number;
  savings: number;
}

export interface DailySummary {
  date: string;
  requests: number;
  inputTokens: number;
  outputTokens: number;
  cost: number;
  savings: number;
}

export interface SavingsReport {
  period: string;
  totalCostWithoutCache: number;
  totalCostWithCache: number;
  totalSavings: number;
  savingsPercent: number;
  cacheHitRate: number;
  byProvider: ProviderSavingsSummary[];
}

export interface ProviderSavingsSummary {
  platform: string;
  totalCost: number;
  savings: number;
  savingsPercent: number;
  cacheHitRate: number;
}

export interface ProviderCost {
  platform: string;
  totalCost: number;
  totalInputTokens: number;
  totalOutputTokens: number;
  requests: number;
  averageCostPerRequest: number;
}

const DSH_CACHE_DISCOUNT = 0.5; // 50% discount for DSH cached tokens

class CostCalculator {
  private db = getDb();

  /**
   * Calculate cost for a specific model
   */
  calculateCost(
    model: string,
    inputTokens: number,
    outputTokens: number,
    cached: boolean = false
  ): CostBreakdown {
    const modelRow = this.db
      .prepare('SELECT platform, paid_input_per_m, paid_output_per_m FROM models WHERE model_id = ? OR display_name = ?')
      .get(model, model) as
      | { platform: string; paid_input_per_m: number | null; paid_output_per_m: number | null }
      | undefined;

    const platform = modelRow?.platform ?? 'unknown';
    const inputCostPerM = modelRow?.paid_input_per_m ?? FALLBACK_INPUT_PER_M;
    const outputCostPerM = modelRow?.paid_output_per_m ?? FALLBACK_OUTPUT_PER_M;

    const inputCost = (inputTokens / 1_000_000) * inputCostPerM;
    const outputCost = (outputTokens / 1_000_000) * outputCostPerM;
    const totalCost = inputCost + outputCost;

    let cacheDiscount = 0;
    let cacheSavings = 0;
    let effectiveCost = totalCost;

    if (cached) {
      cacheDiscount = DSH_CACHE_DISCOUNT;
      cacheSavings = totalCost * cacheDiscount;
      effectiveCost = totalCost * (1 - cacheDiscount);
    }

    return {
      model,
      platform,
      inputTokens,
      outputTokens,
      cached,
      inputCostPerM,
      outputCostPerM,
      inputCost: Math.round(inputCost * 10000) / 10000,
      outputCost: Math.round(outputCost * 10000) / 10000,
      cacheDiscount,
      cacheSavings: Math.round(cacheSavings * 10000) / 10000,
      totalCost: Math.round(totalCost * 10000) / 10000,
      effectiveCost: Math.round(effectiveCost * 10000) / 10000,
    };
  }

  /**
   * Get daily cost report
   */
  getDailyReport(date: string): DailyReport {
    const dateStart = `${date} 00:00:00`;
    const dateEnd = `${date} 23:59:59`;

    // Get hourly aggregates for the day
    const hourlyRows = this.db
      .prepare(`
        SELECT hour, total_requests, success_count, error_count, input_tokens, output_tokens
        FROM request_hourly
        WHERE hour >= ? AND hour <= ?
        ORDER BY hour
      `)
      .all(dateStart.slice(0, 13) + ':00:00', dateEnd.slice(0, 13) + ':00:00') as Array<{
      hour: string;
      total_requests: number;
      success_count: number;
      error_count: number;
      input_tokens: number;
      output_tokens: number;
    }>;

    const totalRequests = hourlyRows.reduce((sum, r) => sum + r.total_requests, 0);
    const totalInputTokens = hourlyRows.reduce((sum, r) => sum + r.input_tokens, 0);
    const totalOutputTokens = hourlyRows.reduce((sum, r) => sum + r.output_tokens, 0);

    // Get per-model breakdown from requests table (with pricing)
    const modelBreakdown = this.db
      .prepare(`
        SELECT
          r.platform,
          r.model_id,
          m.paid_input_per_m,
          m.paid_output_per_m,
          COUNT(*) as requests,
          SUM(r.input_tokens) as input_tokens,
          SUM(r.output_tokens) as output_tokens,
          SUM(r.input_tokens) * COALESCE(m.paid_input_per_m, ?) / 1000000.0 +
          SUM(r.output_tokens) * COALESCE(m.paid_output_per_m, ?) / 1000000.0 as total_cost
        FROM requests r
        LEFT JOIN models m ON m.platform = r.platform AND m.model_id = r.model_id
        WHERE date(r.created_at) = date(?)
        AND r.status = 'success'
        GROUP BY r.platform, r.model_id
      `)
      .all(FALLBACK_INPUT_PER_M, FALLBACK_OUTPUT_PER_M, date) as Array<{
      platform: string;
      model_id: string;
      paid_input_per_m: number | null;
      paid_output_per_m: number | null;
      requests: number;
      input_tokens: number;
      output_tokens: number;
      total_cost: number;
    }>;

    // Get DSH cache stats for the day
    const dshStats = this.db
      .prepare(`
        SELECT
          COUNT(*) as total,
          SUM(CASE WHEN metadata LIKE '%"cache_hit":true%' THEN 1 ELSE 0 END) as cache_hits
        FROM requests
        WHERE date(created_at) = date(?)
      `)
      .get(date) as { total: number; cache_hits: number } | undefined;

    const cacheHitRate = dshStats && dshStats.total > 0 ? dshStats.cache_hits / dshStats.total : 0;

    const byModel: ModelCostSummary[] = modelBreakdown.map((row) => {
      const cost = row.total_cost;
      const savings = cost * cacheHitRate * DSH_CACHE_DISCOUNT;
      return {
        model: row.model_id,
        platform: row.platform,
        requests: row.requests,
        inputTokens: row.input_tokens,
        outputTokens: row.output_tokens,
        cost: Math.round(cost * 10000) / 10000,
        savings: Math.round(savings * 10000) / 10000,
      };
    });

    // Group by provider
    const providerMap = new Map<string, ProviderCostSummary>();
    for (const m of byModel) {
      const existing = providerMap.get(m.platform) || {
        platform: m.platform,
        requests: 0,
        inputTokens: 0,
        outputTokens: 0,
        cost: 0,
        savings: 0,
      };
      existing.requests += m.requests;
      existing.inputTokens += m.inputTokens;
      existing.outputTokens += m.outputTokens;
      existing.cost += m.cost;
      existing.savings += m.savings;
      providerMap.set(m.platform, existing);
    }

    const byProvider = Array.from(providerMap.values());

    const totalCost = byModel.reduce((sum, m) => sum + m.cost, 0);
    const totalSavings = byModel.reduce((sum, m) => sum + m.savings, 0);

    return {
      date,
      totalRequests,
      totalInputTokens,
      totalOutputTokens,
      totalCost: Math.round(totalCost * 10000) / 10000,
      totalSavings: Math.round(totalSavings * 10000) / 10000,
      byModel,
      byProvider,
    };
  }

  /**
   * Get monthly cost report
   */
  getMonthlyReport(month: string): MonthlyReport {
    // month format: YYYY-MM
    const startDate = `${month}-01 00:00:00`;
    const endDate = `${month}-31 23:59:59`; // SQLite handles invalid dates

    // Get daily breakdown
    const dailyRows = this.db
      .prepare(`
        SELECT
          date(created_at) as date,
          COUNT(*) as requests,
          SUM(input_tokens) as input_tokens,
          SUM(output_tokens) as output_tokens
        FROM requests
        WHERE created_at >= ? AND created_at <= ?
        AND status = 'success'
        GROUP BY date(created_at)
        ORDER BY date
      `)
      .all(startDate, endDate) as Array<{
      date: string;
      requests: number;
      input_tokens: number;
      output_tokens: number;
    }>;

    // Get model breakdown for the month
    const modelBreakdown = this.db
      .prepare(`
        SELECT
          r.platform,
          r.model_id,
          m.paid_input_per_m,
          m.paid_output_per_m,
          COUNT(*) as requests,
          SUM(r.input_tokens) as input_tokens,
          SUM(r.output_tokens) as output_tokens,
          SUM(r.input_tokens) * COALESCE(m.paid_input_per_m, ?) / 1000000.0 +
          SUM(r.output_tokens) * COALESCE(m.paid_output_per_m, ?) / 1000000.0 as total_cost
        FROM requests r
        LEFT JOIN models m ON m.platform = r.platform AND m.model_id = r.model_id
        WHERE r.created_at >= ? AND r.created_at <= ?
        AND r.status = 'success'
        GROUP BY r.platform, r.model_id
      `)
      .all(FALLBACK_INPUT_PER_M, FALLBACK_OUTPUT_PER_M, startDate, endDate) as Array<{
      platform: string;
      model_id: string;
      paid_input_per_m: number | null;
      paid_output_per_m: number | null;
      requests: number;
      input_tokens: number;
      output_tokens: number;
      total_cost: number;
    }>;

