      totalOutputTokens: row.output_tokens,
      requests: row.requests,
      averageCostPerRequest: row.requests > 0
        ? Math.round((row.total_cost / row.requests) * 10000) / 10000
        : 0,
    }));
  }

  /**
   * Get top expensive models
   */
  getTopExpensiveModels(limit: number = 10): ModelCostSummary[] {
    const rows = this.db
      .prepare(`
        SELECT
          r.platform,
