/**
 * Provider Health Monitor
 * Pings each provider's models endpoint to check health
 */
class ProviderHealth {
  private db = getDb();
  private monitoring = false;
  private intervalId: ReturnType<typeof setInterval> | null = null;
  private lastResults = new Map<string, HealthReport>();

  private static readonly DEFAULT_INTERVAL_MS = 5 * 60 * 1000; // 5 minutes
  private static readonly HEALTH_CHECK_TIMEOUT = 15000; // 15 seconds

  constructor() {
    this.initHealthTable();
  }

  private initHealthTable(): void {
    // Create health check history table
    this.db.prepare(`
      CREATE TABLE IF NOT EXISTS provider_health_history (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        platform TEXT NOT NULL,
        base_url TEXT,
        healthy INTEGER NOT NULL,
        latency_ms INTEGER NOT NULL,
        error TEXT,
        checked_at TEXT NOT NULL DEFAULT (datetime('now'))
      )
    `).run();

    this.db.prepare(`
      CREATE INDEX IF NOT EXISTS idx_provider_health_platform_time
      ON provider_health_history(platform, checked_at)
    `).run();

    this.db.prepare(`
      CREATE INDEX IF NOT EXISTS idx_provider_health_checked_at
      ON provider_health_history(checked_at)
    `).run();
  }

  /**
   * Check a specific provider by pinging its models endpoint
   */
  async checkProvider(platform: string, baseUrl?: string): Promise<HealthStatus> {
    const startTime = Date.now();
    let healthy = false;
    let error: string | null = null;
    let latencyMs = 0;

    try {
      const provider = resolveProvider(platform as Platform, baseUrl ?? null);
      if (!provider) {
        error = `Provider ${platform} not found`;
        latencyMs = Date.now() - startTime;
        return this.buildHealthStatus(platform, baseUrl ?? null, false, latencyMs, error);
      }

      // Try to find an enabled key for this provider
      const keyRow = this.db
        .prepare(`
          SELECT * FROM api_keys
          WHERE platform = ? AND enabled = 1 AND status IN ('healthy', 'unknown')
          ${baseUrl ? 'AND (base_url = ? OR base_url IS NULL)' : ''}
          ORDER BY created_at ASC
          LIMIT 1
        `)
        .get(platform, baseUrl ?? null) as any;

      if (!keyRow) {
        // No keys available, still try to check provider without auth
        // Some providers allow unauthenticated /models endpoint
        try {
          const result = await Promise.race([
            provider.listModels?.(),
            new Promise((_, reject) =>
              setTimeout(() => reject(new Error('timeout')), ProviderHealth.HEALTH_CHECK_TIMEOUT)
            ),
          ]);
          healthy = !!result;
          latencyMs = Date.now() - startTime;
        } catch (e) {
          error = e instanceof Error ? e.message : String(e);
          healthy = false;
          latencyMs = Date.now() - startTime;
        }
      } else {
        // Use the key to check
        try {
          const apiKey = decrypt(keyRow.encrypted_key, keyRow.iv, keyRow.auth_tag);
          const validation = await Promise.race([
            withKeyProxy(decryptProxyUrl(keyRow), () =>
              provider.validateKey(apiKey, {
                platform: platform as Platform,
                keyId: keyRow.id,
                quotaPoolKey: platform,
                endpoint: 'models',
                origin: 'health',
              })
            ),
            new Promise((_, reject) =>
              setTimeout(() => reject(new Error('timeout')), ProviderHealth.HEALTH_CHECK_TIMEOUT)
            ),
          ]);

          const isValid = typeof validation === 'boolean' ? validation : validation?.valid;
          healthy = isValid;
          latencyMs = Date.now() - startTime;

          if (!isValid) {
            error = typeof validation === 'boolean'
              ? `${provider.name} rejected the API key`
              : validation?.error ?? 'Key validation failed';
          }
        } catch (e) {
          error = e instanceof Error ? e.message : String(e);
          healthy = false;
          latencyMs = Date.now() - startTime;
        }
      }
    } catch (e) {
      error = e instanceof Error ? e.message : String(e);
      healthy = false;
      latencyMs = Date.now() - startTime;
    }

    const status = this.buildHealthStatus(platform, baseUrl ?? null, healthy, latencyMs, error);
    await this.recordHealthCheck(status);
    return status;
  }

  private buildHealthStatus(
    platform: string,
    baseUrl: string | null,
    healthy: boolean,
    latencyMs: number,
    error: string | null
  ): HealthStatus {
    // Calculate uptime from recent history
    const uptime = this.calculateUptime(platform, baseUrl, 'day');

    return {
      platform,
      baseUrl,
      healthy,
      latencyMs,
      error,
      lastChecked: new Date().toISOString(),
      uptime,
    };
  }

  /**
   * Check all providers that have keys configured
   */
  async checkAll(): Promise<HealthReport[]> {
    const providers = this.db
      .prepare(`
        SELECT DISTINCT platform, base_url
        FROM api_keys
        WHERE enabled = 1
      `)
      .all() as Array<{ platform: string; base_url: string | null }>;

    const reports: HealthReport[] = [];

    for (const { platform, base_url } of providers) {
      const status = await this.checkProvider(platform, base_url ?? undefined);
      const uptime24h = this.calculateUptime(platform, base_url, 'day');
      const uptime7d = this.calculateUptime(platform, base_url, 'week');
      const uptime30d = this.calculateUptime(platform, base_url, 'month');

      const stats = this.getCheckStats(platform, base_url);

      const report: HealthReport = {
        platform,
        baseUrl: base_url,
        status: status.healthy ? 'healthy' : 'unhealthy',
        latencyMs: status.latencyMs,
        error: status.error,
        lastChecked: status.lastChecked,
        uptime24h,
        uptime7d,
        uptime30d,
        totalChecks: stats.total,
        successfulChecks: stats.successful,
        failedChecks: stats.failed,
      };

      reports.push(report);
      this.lastResults.set(`${platform}|${base_url ?? ''}`, report);
    }

    return reports;
  }

