/**
 * Auto Discovery Service
 * Discovers new models from FreeLLMAPI catalog and auto-adds them
 */
class AutoDiscovery {
  private db = getDb();
  private syncScheduled = false;
  private intervalId: ReturnType<typeof setInterval> | null = null;
  private lastSyncReport: SyncReport | null = null;

  /**
   * Sync catalog from FreeLLMAPI
   */
  async syncCatalog(force = false): Promise<SyncReport> {
    console.log('[AutoDiscovery] Starting catalog sync...');
    const report = await syncCatalog(force);
    this.lastSyncReport = report;

    if (report.ok && report.action === 'applied' && report.counts) {
      // Find new models that were inserted
      const newModels = await this.findNewModels(report.counts.inserted);
      report.newModels = newModels;
      console.log(`[AutoDiscovery] Sync complete: ${newModels.length} new models discovered`);
    }

    return report;
  }

  /**
   * Find newly added models after a sync
   */
  private async findNewModels(insertedCount: number): Promise<ModelInfo[]> {
    if (insertedCount === 0) return [];

    // Get recently added models (source = 'catalog', ordered by insertion)
    // We can't directly tell which were just added, so we look for models
    // that don't have a fallback_config entry older than the sync
    const rows = this.db
      .prepare(`
        SELECT m.platform, m.model_id, m.display_name, m.intelligence_rank,
               m.speed_rank, m.size_label, m.context_window, m.supports_vision,
               m.supports_tools, m.rpm_limit, m.rpd_limit, m.tpm_limit,
               m.tpd_limit, m.monthly_token_budget
        FROM models m
        WHERE m.source = 'catalog'
        ORDER BY m.id DESC
        LIMIT ?
      `)
      .all(insertedCount) as Array<{
      platform: string;
      model_id: string;
      display_name: string;
      intelligence_rank: number;
      speed_rank: number;
      size_label: string;
      context_window: number | null;
      supports_vision: number;
      supports_tools: number;
      rpm_limit: number | null;
      rpd_limit: number | null;
      tpm_limit: number | null;
      tpd_limit: number | null;
      monthly_token_budget: string | null;
    }>;

    return rows.map((row) => ({
      platform: row.platform,
      modelId: row.model_id,
      displayName: row.display_name,
      intelligenceRank: row.intelligence_rank,
      speedRank: row.speed_rank,
      sizeLabel: row.size_label,
      contextWindow: row.context_window,
      supportsVision: row.supports_vision === 1,
      supportsTools: row.supports_tools === 1,
      limits: {
        rpm: row.rpm_limit,
        rpd: row.rpd_limit,
        tpm: row.tpm_limit,
        tpd: row.tpd_limit,
      },
      monthlyTokenBudget: row.monthly_token_budget,
    }));
  }

  /**
   * Find new providers in catalog that we don't have keys for
   */
  async findNewProviders(): Promise<string[]> {
    const state = getSyncState();

    if (!state.appliedVersion) {
      return [];
    }

    // Get all platforms from the catalog that we know about
    const catalogPlatforms = this.db
      .prepare('SELECT DISTINCT platform FROM models WHERE source = "catalog"')
      .all() as Array<{ platform: string }>;

    // Get platforms we already have keys for
    const keyPlatforms = this.db
      .prepare('SELECT DISTINCT platform FROM api_keys WHERE enabled = 1')
      .all() as Array<{ platform: string }>;

    const knownPlatforms = new Set(keyPlatforms.map((p) => p.platform));
    const newProviders = catalogPlatforms
      .map((p) => p.platform)
      .filter((p) => !knownPlatforms.has(p) && hasProvider(p as any));

    return newProviders;
  }

  /**
   * Auto-add discovered models (enable them if they're from known providers)
   */
  async autoAddModels(models: ModelInfo[]): Promise<number> {
