               m.tpd_limit, m.monthly_token_budget
        FROM models m
        LEFT JOIN fallback_config f ON m.id = f.model_db_id
        WHERE m.source = 'catalog'
        AND f.id IS NULL
        ORDER BY m.id DESC
        LIMIT ?
      `)
      .all(limit) as Array<{
      platform: string;
      model_id: string;
      display_name: string;
      intelligence_rank: number;
      speed_rank: number;
      size_label: string;
      context_window: number | null;
      supports_vision: number;
      supports_tools: number;
      rpm_limit: number | null;
      rpd_limit: number | null;
      tpm_limit: number | null;
      tpd_limit: number | null;
      monthly_token_budget: string | null;
    }>;

    return rows.map((row) => ({
      platform: row.platform,
      modelId: row.model_id,
      displayName: row.display_name,
      intelligenceRank: row.intelligence_rank,
      speedRank: row.speed_rank,
      sizeLabel: row.size_label,
      contextWindow: row.context_window,
      supportsVision: row.supports_vision === 1,
      supportsTools: row.supports_tools === 1,
      limits: {
        rpm: row.rpm_limit,
        rpd: row.rpd_limit,
        tpm: row.tpm_limit,
        tpd: row.tpd_limit,
      },
      monthlyTokenBudget: row.monthly_token_budget,
    }));
  }

  /**
   * Start scheduled sync
   */
  startScheduledSync(intervalHours: number = 12): void {
    if (this.syncScheduled) return;

    if (process.env.CATALOG_SYNC_DISABLED === '1') {
      console.log('[AutoDiscovery] Scheduled sync disabled via CATALOG_SYNC_DISABLED=1');
      return;
    }

    const intervalMs = intervalHours * 60 * 60 * 1000;
    console.log(`[AutoDiscovery] Starting scheduled sync every ${intervalHours}h`);

    this.syncScheduled = true;

    // Run initial sync after a short delay
    setTimeout(() => {
      this.syncCatalog().catch((err) => {
        console.error('[AutoDiscovery] Initial sync failed:', err);
      });
    }, 10000);

    this.intervalId = setInterval(() => {
      this.syncCatalog().catch((err) => {
        console.error('[AutoDiscovery] Scheduled sync failed:', err);
      });
    }, intervalMs);
  }

  /**
   * Stop scheduled sync
   */
  stopScheduledSync(): void {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
    this.syncScheduled = false;
    console.log('[AutoDiscovery] Scheduled sync stopped');
  }

