  async forceSync(): Promise<SyncReport> {
    return this.syncCatalog(true);
  }

  /**
   * Get last sync report
   */
  getLastSyncReport(): SyncReport | null {
    return this.lastSyncReport;
  }

  /**
   * Re-apply cached catalog (e.g., after boot)
   */
  reapplyCache(): { reapplied: boolean; version?: string } {
    return reapplyCachedCatalog();
  }
}

