import type { Request, Response } from 'express';
import { costCalculator } from '../services/costCalculator.js';
import { requireAuth } from '../middleware/requireAuth.js';

export const costRouter = Router();

// All routes require authentication
costRouter.use(requireAuth);

// GET /api/cost/daily - Daily cost report
costRouter.get('/daily', (req: Request, res: Response) => {
  const date = (req.query.date as string) || new Date().toISOString().split('T')[0];
  const report = costCalculator.getDailyReport(date);
  res.json(report);
});

// GET /api/cost/monthly - Monthly cost report
costRouter.get('/monthly', (req: Request, res: Response) => {
  const month = (req.query.month as string) || new Date().toISOString().slice(0, 7); // YYYY-MM
  const report = costCalculator.getMonthlyReport(month);
  res.json(report);
});

// GET /api/cost/provider/:platform - Cost per provider
costRouter.get('/provider/:platform', (req: Request, res: Response) => {
  const platform = req.params.platform;
  const costs = costCalculator.getProviderCosts();
  const providerCost = costs.find((c) => c.platform === platform);

  if (!providerCost) {
    res.status(404).json({ error: { message: `Provider ${platform} not found` } });
    return;
  }

  res.json(providerCost);
});

// GET /api/cost/providers - All providers costs
costRouter.get('/providers', (_req: Request, res: Response) => {
  const costs = costCalculator.getProviderCosts();
  res.json(costs);
});

// GET /api/cost/savings - Savings calculator
costRouter.get('/savings', (req: Request, res: Response) => {
  const period = (req.query.period as 'day' | 'month') || 'day';
  const report = costCalculator.calculateSavings(period);
  res.json(report);
});

// GET /api/cost/top - Top expensive models
costRouter.get('/top', (req: Request, res: Response) => {
  const limit = parseInt(req.query.limit as string, 10) || 10;
  const models = costCalculator.getTopExpensiveModels(limit);
  res.json(models);
});

// GET /api/cost/calculate - Calculate cost for specific usage
costRouter.get('/calculate', (req: Request, res: Response) => {
  const model = req.query.model as string;
