{"content":"/**
 * DeepSeek Harness Integration
 * Provides tracing and fallback capabilities using DeepSeek Harness
 */

import { execSync } from 'child_process';
import { getDb } from '../db/index.js';
import { costCalculator } from './costCalculator.js';

// Simple logger using console
const logger = {
  info: (msg: string) => console.log(`[deepseek-harness] ${msg}`),
  warn: (msg: string) => console.warn(`[deepseek-harness] ${msg}`),
  error: (msg: string) => console.error(`[deepseek-harness] ${msg}`),
};

interface CacheStats {
  hits: number;
  misses: number;
  hitRate: number;
  totalSaved: number;
}

interface CostSavings {
  period: string;
  totalCostWithoutCache: number;
  totalCostWithCache: number;
  totalSavings: number;
  savingsPercent: number;
}

const db = getDb();

/**
 * Initialize the DSH tracking tables
 */
function initTrackingTables(): void {
  db.prepare(`
    CREATE TABLE IF NOT EXISTS dsh_cache_stats (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      model TEXT NOT NULL,
      cache_hit INTEGER NOT NULL,
      input_tokens INTEGER NOT NULL DEFAULT 0,
      output_tokens INTEGER NOT NULL DEFAULT 0,
      saved_cost REAL NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    )
  `).run();

  db.prepare(`
    CREATE INDEX IF NOT EXISTS idx_dsh_cache_stats_model_time
    ON dsh_cache_stats(model, created_at)
  `).run();

  db.prepare(`
    CREATE INDEX IF NOT EXISTS idx_dsh_cache_stats_created_at
    ON dsh_cache_stats(created_at)
  `).run();
}

initTrackingTables();

/**
 * Execute a DeepSeek Harness command
 */
export function executeDeepSeekHarness(command: string, args: Record<string, any>): any {
  try {
    const argString = Object.entries(args)
      .map(([key, value]) => {
        if (typeof value === 'string') {
          return `--${key} "${value}"`;
        } else if (typeof value === 'boolean') {
          return value ? `--${key}` : '';
        } else {
          return `--${key} ${JSON.stringify(value)}`;
        }
      })
      .filter(Boolean)
      .join(' ');

    const fullCommand = `dsh ${command} ${argString}`;
    logger.info(`Executing DeepSeek Harness: ${fullCommand}`);

    const output = execSync(fullCommand, {
      encoding: 'utf8',
      timeout: 30000,
    });

    try {
      return JSON.parse(output);
    } catch (e) {
      return output;
    }
  } catch (error) {
    logger.error(`DeepSeek Harness error: ${(error as Error).message}`);
    throw new Error(`DeepSeek Harness failed: ${(error as Error).message}`);
  }
}

/**
 * Trace a request using DeepSeek Harness
 */
export function traceWithDeepSeekHarness(
  model: string,
  input: any,
  output: any,
  metadata: Record<string, any> = {}
): void {
  try {
    executeDeepSeekHarness('trace', {
      model,
      input: JSON.stringify(input),
      output: JSON.stringify(output),
      ...metadata,
    });
    logger.info(`Traced request with DeepSeek Harness: ${model}`);
  } catch (error) {
    logger.warn(`Failed to trace with DeepSeek Harness: ${(error as Error).message}`);
  }
}

/**
 * Use DeepSeek Harness as a fallback provider
 */
export async function deepseekHarnessFallback(
  model: string,
  messages: any[],
  options: Record<string, any> = {}
): Promise<any> {
  try {
    const result = executeDeepSeekHarness('chat', {
      model,
      messages: JSON.stringify(messages),
      ...options,
    });

    return {
      choices: [
        {
          message: {
            role: 'assistant',
            content: result.choices?.[0]?.message?.content || result.output || result,
          },
        },
      ],
      model,
      usage: result.usage || { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
    };
  } catch (error) {
    logger.error(`DeepSeek Harness fallback failed: ${(error as Error).message}`);
    throw error;
  }
}

/**
 * Check if DeepSeek Harness is available
 */
export function isDeepSeekHarnessAvailable(): boolean {
  try {
