{"content":"/**
 * DeepSeek Harness Integration
 * Provides tracing and fallback capabilities using DeepSeek Harness
 */

import { execSync } from 'child_process';
import { getDb } from '../db/index.js';
import { costCalculator } from './costCalculator.js';

// Simple logger using console
const logger = {
  info: (msg: string) => console.log(`[deepseek-harness] ${msg}`),
  warn: (msg: string) => console.warn(`[deepseek-harness] ${msg}`),
  error: (msg: string) => console.error(`[deepseek-harness] ${msg}`),
};

interface CacheStats {
  hits: number;
  misses: number;
  hitRate: number;
  totalSaved: number;
}

interface CostSavings {
  period: string;
  totalCostWithoutCache: number;
  totalCostWithCache: number;
  totalSavings: number;
  savingsPercent: number;
}

const db = getDb();

/**
 * Initialize the DSH tracking tables
 */
function initTrackingTables(): void {
  db.prepare(`
    CREATE TABLE IF NOT EXISTS dsh_cache_stats (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      model TEXT NOT NULL,
      cache_hit INTEGER NOT NULL,
      input_tokens INTEGER NOT NULL DEFAULT 0,
      output_tokens INTEGER NOT NULL DEFAULT 0,
      saved_cost REAL NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    )
  `).run();

  db.prepare(`
    CREATE INDEX IF NOT EXISTS idx_dsh_cache_stats_model_time
    ON dsh_cache_stats(model, created_at)
  `).run();

  db.prepare(`
    CREATE INDEX IF NOT EXISTS idx_dsh_cache_stats_created_at
    ON dsh_cache_stats(created_at)
  `).run();
}

initTrackingTables();

/**
 * Execute a DeepSeek Harness command
 */
export function executeDeepSeekHarness(command: string, args: Record<string, any>): any {
  try {
    const argString = Object.entries(args)
      .map(([key, value]) => {
        if (typeof value === 'string') {
          return `--${key} "${value}"`;
        } else if (typeof value === 'boolean') {
          return value ? `--${key}` : '';
        } else {
          return `--${key} ${JSON.stringify(value)}`;
        }
      })
      .filter(Boolean)
      .join(' ');

    const fullCommand = `dsh ${command} ${argString}`;
    logger.info(`Executing DeepSeek Harness: ${fullCommand}`);

    const output = execSync(fullCommand, {
      encoding: 'utf8',
      timeout: 30000,
    });

    try {
      return JSON.parse(output);
    } catch (e) {
      return output;
    }
  } catch (error) {
    logger.error(`DeepSeek Harness error: ${(error as Error).message}`);
    throw new Error(`DeepSeek Harness failed: ${(error as Error).message}`);
  }
}

/**
 * Trace a request using DeepSeek Harness
 */
export function traceWithDeepSeekHarness(
  model: string,
  input: any,
  output: any,
  metadata: Record<string, any> = {}
): void {
  try {
    executeDeepSeekHarness('trace', {
      model,
      input: JSON.stringify(input),
      output: JSON.stringify(output),
      ...metadata,
    });
    logger.info(`Traced request with DeepSeek Harness: ${model}`);
  } catch (error) {
    logger.warn(`Failed to trace with DeepSeek Harness: ${(error as Error).message}`);
  }
}

/**
 * Use DeepSeek Harness as a fallback provider
 */
export async function deepseekHarnessFallback(
  model: string,
  messages: any[],
  options: Record<string, any> = {}
): Promise<any> {
  try {
    const result = executeDeepSeekHarness('chat', {
      model,
      messages: JSON.stringify(messages),
      ...options,
    });

    return {
      choices: [
        {
          message: {
            role: 'assistant',
            content: result.choices?.[0]?.message?.content || result.output || result,
          },
        },
      ],
      model,
      usage: result.usage || { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
    };
  } catch (error) {
    logger.error(`DeepSeek Harness fallback failed: ${(error as Error).message}`);
    throw error;
  }
}

/**
 * Check if DeepSeek Harness is available
 */
export function isDeepSeekHarnessAvailable(): boolean {
  try {
    execSync('dsh --version', { encoding: 'utf8', timeout: 5000 });
    return true;
  } catch (error) {
    logger.warn(`DeepSeek Harness not available: ${(error as Error).message}`);
    return false;
  }
}

/**
 * Record a cache hit/miss for DSH
 */
export function recordCacheHit(
  model: string,
  inputTokens: number,
  outputTokens: number,
  isHit: boolean
): void {
  const breakdown = costCalculator.calculateCost(model, inputTokens, outputTokens, isHit);
  const savedCost = isHit ? breakdown.cacheSavings : 0;

  db.prepare(`
    INSERT INTO dsh_cache_stats (model, cache_hit, input_tokens, output_tokens, saved_cost)
    VALUES (?, ?, ?, ?, ?)
  `).run(model, isHit ? 1 : 0, inputTokens, outputTokens, savedCost);

  logger.info(`DSH Cache ${isHit ? 'HIT' : 'MISS'} for ${model}: saved $${savedCost.toFixed(6)}`);
}

/**
 * Get cache statistics for a model or all models
 */
export function getCacheStats(model?: string, period: 'day' | 'week' | 'month' = 'day'): CacheStats {
  const now = new Date();
  let startDate: string;

  switch (period) {
    case 'day':
      startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate()).toISOString();
      break;
    case 'week':
      startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 7).toISOString();
      break;
    case 'month':
      startDate = new Date(now.getFullYear(), now.getMonth(), 1).toISOString();
      break;
  }

  let query = `
    SELECT
      SUM(CASE WHEN cache_hit = 1 THEN 1 ELSE 0 END) as hits,
      SUM(CASE WHEN cache_hit = 0 THEN 1 ELSE 0 END) as misses,
      SUM(saved_cost) as total_saved
    FROM dsh_cache_stats
    WHERE created_at >= ?
  `;
  const params: any[] = [startDate];

  if (model) {
    query += ' AND model = ?';
    params.push(model);
  }

  const row = db.prepare(query).get(...params) as { hits: number; misses: number; total_saved: number };

  const hits = row.hits || 0;
  const misses = row.misses || 0;
  const total = hits + misses;

  return {
    hits,
    misses,
    hitRate: total > 0 ? hits / total : 0,
    totalSaved: row.total_saved || 0,
  };
}

/**
 * Get cost savings from DSH caching
 */
export function getCostSavings(period: 'day' | 'week' | 'month' = 'day'): CostSavings {
  const now = new Date();
  let startDate: string;

  switch (period) {
    case 'day':
      startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate()).toISOString();
      break;
    case 'week':
      startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 7).toISOString();
      break;
    case 'month':
      startDate = new Date(now.getFullYear(), now.getMonth(), 1).toISOString();
      break;
  }

  const stats = getCacheStats(undefined, period);

  // Calculate total cost without cache (all requests at full price)
  // We estimate this from the cache miss cost + what hits would have cost
  const costWithoutCache = stats.totalSaved / 0.5; // Since cache discount is 50%
  const costWithCache = costWithoutCache - stats.totalSaved;

  return {
    period,
    totalCostWithoutCache: costWithoutCache,
    totalCostWithCache: costWithCache,
    totalSavings: stats.totalSaved,
    savingsPercent: costWithoutCache > 0 ? (stats.totalSaved / costWithoutCache) * 100 : 0,
  };
}

/**
 * Get cache stats by model
 */
export function getCacheStatsByModel(period: 'day' | 'week' | 'month' = 'day'): Array<{ model: string; stats: CacheStats }> {
  const now = new Date();
  let startDate: string;

  switch (period) {
    case 'day':
      startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate()).toISOString();
      break;
    case 'week':
      startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 7).toISOString();
      break;
    case 'month':
      startDate = new Date(now.getFullYear(), now.getMonth(), 1).toISOString();
      break;
  }

  const rows = db.prepare(`
    SELECT model,
      SUM(CASE WHEN cache_hit = 1 THEN 1 ELSE 0 END) as hits,
      SUM(CASE WHEN cache_hit = 0 THEN 1 ELSE 0 END) as misses,
      SUM(saved_cost) as total_saved
    FROM dsh_cache_stats
    WHERE created_at >= ?
    GROUP BY model
    ORDER BY total_saved DESC
  `).all(startDate) as Array<{ model: string; hits: number; misses: number; total_saved: number }>;

  return rows.map((row) => {
    const hits = row.hits || 0;
    const misses = row.misses || 0;
    const total = hits + misses;
    return {
      model: row.model,
      stats: {
        hits,
        misses,
        hitRate: total > 0 ? hits / total : 0,
        totalSaved: row.total_saved || 0,
      },
    };
  });
}

/**
 * Export cache stats to Cost Calculator
 */
export function exportToCostCalculator(): void {
  // The cost calculator already reads from requests table
  // This function can be used to sync any additional DSH-specific data
  logger.info('Exporting DSH stats to Cost Calculator');
}

/**
 * Initialize DeepSeek Harness
 */
if (isDeepSeekHarnessAvailable()) {
  logger.info('DeepSeek Harness is available and ready');
} else {
  logger.warn('DeepSeek Harness is not available');
}

export default {
  executeDeepSeekHarness,
  traceWithDeepSeekHarness,
  deepseekHarnessFallback,
  isDeepSeekHarnessAvailable,
  recordCacheHit,
  getCacheStats,
  getCostSavings,
  getCacheStatsByModel,
  exportToCostCalculator,
};","file_path":"/home/ji/projects/jimesh/server/src/services/deepseekHarness.ts"}

