async syncCatalog(force = false): Promise<SyncReport> {
  console.log('[AutoDiscovery] Starting catalog sync...');
  const result = await syncCatalog(force);

  // Convert SyncResult to SyncReport (extended with newModels)
  const report: SyncReport = {
    ok: result.ok,
    action: result.action,
    version: result.version,
    tier: result.tier,
    detail: result.detail,
    counts: result.counts,
  };

  if (result.ok && result.action === 'applied' && result.counts) {
    // Find new models that were inserted
    const newModels = await this.findNewModels(result.counts.inserted);
    report.newModels = newModels;
    console.log(`[AutoDiscovery] Sync complete: ${newModels.length} new models discovered`);
  }

  this.lastSyncReport = report;
  return report;
}

