{"content": "import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import {
  Activity,
  AlertCircle,
  CheckCircle2,
  Clock,
  Pause,
  Play,
  RefreshCw,
  XCircle,
  Zap,
} from 'lucide-react'
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, LineChart, Line } from 'recharts'
import { apiFetch } from '@/lib/api'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'

interface HealthStatus {
  platform: string
  baseUrl: string | null
  healthy: boolean
  latencyMs: number
  error: string | null
  lastChecked: string
  uptime: number
}

interface HealthReport {
  platform: string
  baseUrl: string | null
  status: 'healthy' | 'degraded' | 'unhealthy'
  latencyMs: number
  error: string | null
  lastChecked: string
  uptime24h: number
  uptime7d: number
  uptime30d: number
  totalChecks: number
  successfulChecks: number
  failedChecks: number
}

interface UptimeStats {
  platform: string
  period: string
  uptime: number
  totalChecks: number
  successfulChecks: number
  avgLatencyMs: number
  lastCheck: string | null
  downtimeIncidents: DowntimeIncident[]
}

interface DowntimeIncident {
  start: string
  end: string | null
  durationMs: number | null
  error: string
}

export function ProviderHealthDashboard() {
  const [selectedPlatform, setSelectedPlatform] = useState<string | null>(null)
  const [monitoring, setMonitoring] = useState(false)
  const queryClient = useQueryClient()

  // Get all provider health reports
  const providersQuery = useQuery<HealthReport[]>({
    queryKey: ['health', 'providers'],
    queryFn: async () => {
      const res = await apiFetch('/api/health/providers')
      if (!res.ok) throw new Error('Failed to fetch health')
      return res.json()
    },
    refetchInterval: 30000, // refresh every 30s
  })

  // Get uptime for selected platform
  const uptimeQuery = useQuery<UptimeStats>({
    queryKey: ['health', 'uptime', selectedPlatform],
    queryFn: async () => {
      if (!selectedPlatform) return null
      const res = await apiFetch(`/api/health/uptime/${selectedPlatform}?period=day`)
      if (!res.ok) throw new Error('Failed to fetch uptime')
      return res.json()
    },
    enabled: !!selectedPlatform,
  })

  // Trigger health check
  const checkMutation = useMutation({
    mutationFn: async () => {
      const res = await apiFetch('/api/health/check', { method: 'POST' })
      if (!res.ok) throw new Error('Check failed')
