  appliedTier: string | null
  nextSyncIn: number | null
  newModelsCount: number
  autoSyncEnabled: boolean
}

interface ModelInfo {
  platform: string
  modelId: string
  displayName: string
  intelligenceRank: number
  speedRank: number
  sizeLabel: string
  contextWindow: number | null
  supportsVision: boolean
  supportsTools: boolean
  limits: {
    rpm: number | null
    rpd: number | null
    tpm: number | null
    tpd: number | null
  }
  monthlyTokenBudget: string | null
}

interface SyncReport {
  ok: boolean
  action: string
  version?: string
  tier?: string
  detail?: string
  counts?: {
    updated: number
    inserted: number
    removed: number
    skippedUnknownPlatform: number
    quirks: number
  }
  newModels?: ModelInfo[]
}

function formatTimeUntil(ms: number | null): string {
