          </CardHeader>
          <CardContent>
            <pre className="text-sm bg-red-50 dark:bg-red-900/20 p-3 rounded overflow-auto">
              {status.lastError}
            </pre>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

